firewall.terminal:
table inet wayvia_terminal {
	chain output {
		type filter hook output priority filter; policy drop;
		oifname "lo" accept
		oifname "wayvia-tun" accept
		ct state established,related accept
		ip daddr 10.71.0.0/24 accept
		ip6 daddr fd72:1::/64 accept
		meta l4proto ipv6-icmp accept
		ip daddr 10.72.0.1 tcp dport 443 accept
	}
}

firewall.ali:
table ip lab_unprotected_baseline {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		ip saddr 10.89.0.0/30 oifname "aja" masquerade
	}
}
table inet wayvia_guard {
	chain input {
		type filter hook input priority filter - 10; policy accept;
		iifname "wayvia-host" ip saddr 10.89.0.2 tcp dport 1080 accept
		tcp dport 1080 counter packets 0 bytes 0 drop
	}
}

firewall.wayvia-egress:
table inet wayvia_guard {
	chain output {
		type filter hook output priority filter - 10; policy drop;
		oifname "lo" accept
		ct state established,related accept
		oifname "tun0" meta nfproto ipv4 accept
		ip daddr 10.89.0.1 tcp dport 1080 accept
		counter packets 11 bytes 672 drop
	}

	chain input {
		type filter hook input priority filter - 10; policy drop;
		iifname "lo" accept
		ct state established,related accept
		ip saddr 10.89.0.1 tcp dport 1081 accept
		iifname "wayvia-ns" ip saddr 10.89.0.1 udp dport 1024-65535 accept
	}
}

firewall.jp:
table inet wayvia_exit {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		ip saddr 10.77.0.0/24 oifname "jfa" counter packets 7 bytes 380 masquerade
	}
}
